import{_ as o,r as n,o as e,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"加载指示器 - October CMS - 3.x","titleTemplate":false,"description":"指示页面当前正在加载。","frontmatter":{"subtitle":"指示页面当前正在加载。"},"headers":[{"level":2,"title":"进度条","slug":"进度条","link":"#进度条","children":[]},{"level":2,"title":"加载按钮","slug":"加载按钮","link":"#加载按钮","children":[]},{"level":2,"title":"切换元素","slug":"切换元素","link":"#切换元素","children":[{"level":3,"title":"检测全局请求","slug":"检测全局请求","link":"#检测全局请求","children":[]},{"level":3,"title":"针对特定处理程序","slug":"针对特定处理程序","link":"#针对特定处理程序","children":[]}]},{"level":2,"title":"使用 JavaScript","slug":"使用-javascript","link":"#使用-javascript","children":[]}],"relativePath":"3.x/zh-cn/cms/features/loaders.md","filePath":"3.x/zh-cn/cms/features/loaders.md"}'),i={name:"3.x/zh-cn/cms/features/loaders.md"};function k(r,a,d,g,m,h){const t=n("pre-heading"),p=n("post-heading");return e(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"加载指示器",-1)),s(p),a[1]||(a[1]=u(`<p>当 AJAX 框架向服务器发出请求时，显示加载指示器是一个好做法，因为页面可能不会立即更新。有多种方法和标准加载指示器可以清楚地表明 AJAX 请求已触发并正在进行中。</p><h2 id="进度条"><a href="#进度条" class="header-anchor">#</a> 进度条</h2><p>AJAX 框架的一个显著特性是当 AJAX 请求运行时，页面顶部会显示一个进度条。进度条监听 AJAX 请求，当请求耗时超过 300 毫秒时出现，请求完成后再次隐藏。</p><p>要为某个请求禁用进度条，请将 <code>data-request-progress-bar</code> 属性设置为 <code>false</code>。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDoSomething<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-progress-bar</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Do something
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>在 JavaScript 中，将 AJAX 请求的 <code>progressBar</code> 选项设置为 <code>false</code>。</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">ajax</span><span class="token punctuation">(</span><span class="token string">&#39;onSilentRequest&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">progressBar</span><span class="token operator">:</span> <span class="token boolean">false</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>要全局禁用进度条，请使用样式表将 <code>visibility</code> 样式设置为 <code>hidden</code>。</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">.oc-progress-bar</span> <span class="token punctuation">{</span>
    <span class="token property">visibility</span><span class="token punctuation">:</span> hidden<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>你可以使用 JavaScript 通过 <code>oc.progressBar</code> 对象和 <code>show</code> / <code>hide</code> 函数来显示进度条。</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span>progressBar<span class="token punctuation">.</span><span class="token function">show</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

oc<span class="token punctuation">.</span>progressBar<span class="token punctuation">.</span><span class="token function">hide</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="加载按钮"><a href="#加载按钮" class="header-anchor">#</a> 加载按钮</h2><p>提交表单时，用户可能会意外地双击按钮导致重复提交，加载按钮可以解决这个问题。在 AJAX 请求期间，具有 <code>data-attach-loading</code> 属性的按钮元素将被禁用，并添加 CSS 类 <code>oc-attach-loader</code>。此类将使用 <code>:after</code> CSS 选择器在按钮和锚点元素上生成一个加载旋转图标。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>#<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDoSomething<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
    Do Something
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>当按钮位于包含 <code>oc-attach-loader</code> 属性的表单内时，将显示加载指示器。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSubmit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-attach-loading</span><span class="token punctuation">&gt;</span></span>
        Submit
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>由于输入元素不支持 <code>:after</code> CSS 选择器，因此会在它们后面插入一个新元素。该元素在 AJAX 请求完成后被移除。这在使用 <code>data-track-input</code> 属性监视输入变化并提交 AJAX 请求时非常有用。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>username<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onCheckUsername<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-track-input</span>
    <span class="token attr-name">data-attach-loading</span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>你可以使用 <code>oc.attachLoader</code> 对象和 <code>show</code> / <code>hide</code> 函数手动向按钮添加加载器，将元素选择器或对象作为第一个参数传递。</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span>attachLoader<span class="token punctuation">.</span><span class="token function">show</span><span class="token punctuation">(</span><span class="token string">&#39;.my-element&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

oc<span class="token punctuation">.</span>attachLoader<span class="token punctuation">.</span><span class="token function">hide</span><span class="token punctuation">(</span><span class="token string">&#39;.my-element&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="切换元素"><a href="#切换元素" class="header-anchor">#</a> 切换元素</h2><p>你可以使用 <code>data-request-loading</code> 属性使元素在 AJAX 请求期间可见。该值是一个 CSS 选择器，使用 <code>block</code> 和 <code>none</code> 的 display 属性来管理元素的可见性。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onPay<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-loading</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>.is-loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Pay Now
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token special-attr"><span class="token attr-name">style</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value css language-css"><span class="token property">display</span><span class="token punctuation">:</span>none</span><span class="token punctuation">&quot;</span></span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>is-loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Processing Payment...
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="检测全局请求"><a href="#检测全局请求" class="header-anchor">#</a> 检测全局请求</h3><p>你可以通过检查 HTML 元素上的 <code>data-ajax-progress</code> 属性来检测全局 AJAX 请求是否正在进行中。在样式表中表示如下。</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">html[data-ajax-progress]</span> <span class="token punctuation">{</span>
    <span class="token comment">/* Display loading indicators */</span>
<span class="token punctuation">}</span>
</code></pre></div><p>该属性也会添加到表单元素上。</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">form[data-ajax-progress]</span> <span class="token punctuation">{</span>
    <span class="token comment">/* The form is loading */</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="针对特定处理程序"><a href="#针对特定处理程序" class="header-anchor">#</a> 针对特定处理程序</h3><p>在某些情况下，你可能希望为特定的 <a href="./../ajax/handlers.html">AJAX 处理程序事件</a> 显示加载指示器，<code>data-ajax-progress</code> 属性将包含最近的处理程序名称，这可以用于针对特定请求。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onPay<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Pay Now<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onCancel<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Cancel<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>is-payment-loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        Processing Payment...
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>这可以使用样式表属性值选择器来实现。</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">.is-payment-loading</span> <span class="token punctuation">{</span>
    <span class="token property">display</span><span class="token punctuation">:</span> none<span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token selector">form[data-ajax-progress=onPay] .is-payment-loading</span> <span class="token punctuation">{</span>
    <span class="token property">display</span><span class="token punctuation">:</span> block<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="使用-javascript"><a href="#使用-javascript" class="header-anchor">#</a> 使用 JavaScript</h2><p>对于更复杂的场景，你可以使用 <code>ajax:promise</code> 和 <code>ajax:always</code> 事件挂接到 <a href="./../ajax/javascript-api.html">AJAX JavaScript API</a>。这些事件可以附加到文档、表单或目标元素上。</p><div class="language-js extra-class"><pre class="language-js"><code>formElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:promise&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// A new request has started</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

formElement<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:always&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// A request has ended</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>以下示例将在请求运行期间禁用表单内的所有输入元素。</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:promise&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">closest</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">el</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        el<span class="token punctuation">.</span>disabled <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:always&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span>target<span class="token punctuation">.</span><span class="token function">closest</span><span class="token punctuation">(</span><span class="token string">&#39;form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">querySelectorAll</span><span class="token punctuation">(</span><span class="token string">&#39;input&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">el</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        el<span class="token punctuation">.</span>disabled <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,38))])}const q=o(i,[["render",k]]);export{f as __pageData,q as default};
